actions.script:
import groovy.json.JsonOutput

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_PRODUCT_CATEGORY_COMPLIANCE',
                 startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([productId: productId]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    // find#ProductFeatureGroups defaults applTypeEnumId to "PfatSelectable" (commercial
    // variant-generating groups like Color/Size); our norm-derived requirement groups
    // use "PfatStandard" (intrinsic, non-variant characteristics) instead, so it must be
    // passed explicitly -- an empty string does NOT fall through the service's own
    // ignore-if-empty condition the way a literally-absent parameter would.
    Map groupResult = ec.service.sync().name('mantle.product.ProductServices.find#ProductFeatureGroups')
            .parameters([productId: productId, applTypeEnumId: 'PfatStandard']).call()
    List featureGroups = groupResult.productFeatureGroupList ?: []

    results = []
    featureGroups.each { Map group ->
        String featureGroupId = group.productFeatureGroupId as String
        List groupAppls = ec.entity.find('mantle.product.feature.ProductFeatureGroupAppl')
                .condition('productFeatureGroupId', featureGroupId)
                .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
                .list()
        groupAppls.each { groupAppl ->
            String productFeatureId = groupAppl.productFeatureId as String
            def feature = ec.entity.find('mantle.product.feature.ProductFeature')
                    .condition('productFeatureId', productFeatureId).one()
            def actualAppl = ec.entity.find('mantle.product.feature.ProductFeatureAppl')
                    .condition('productId', productId)
                    .condition('productFeatureId', productFeatureId)
                    .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp)
                    .list()
            results.add([
                productFeatureGroupId: featureGroupId,
                productFeatureId     : productFeatureId,
                description          : feature?.description,
                status               : actualAppl ? 'SATISFIED' : 'MISSING'
            ])
        }
    }

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(results)])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
